/**
 * Layout mode, asked what it meant.
 *
 * Layout mode ("L" in the toolbar) lets a reviewer drag a new component onto the
 * page or move and resize an existing one. It lands — the annotation is created,
 * synced and stored with full geometry — but it lands without intent:
 *
 *   - `comment` is GENERATED by the toolbar: "Move Hero section (section) —
 *     from (12,340) 400×200 to (36,240) 400×200". Coordinates, not a reason.
 *   - `intent` is hardcoded `"change"` and `severity` hardcoded `"important"`
 *     on every layout annotation the toolbar has ever written, so the two fields
 *     that exist to carry intent carry none.
 *
 * The rects are viewport coordinates from one person's browser, so a bare drag
 * cannot be applied literally by anything. It means something — "this should
 * come first", "these two belong together" — and that meaning only exists in the
 * head of whoever dragged it, for about as long as the tab stays open.
 *
 * This asks them, then, while they still remember.
 *
 * ⚠️ WHY THIS LISTENS TO THE SERVER AND NOT THE TOOLBAR
 * The obvious hook is `onAnnotationAdd`. It does not fire for layout: the prop
 * has exactly one call site in `agentation@3.0.2`, inside the feedback-popup
 * submit path. Placement and rearrange are synced from a `useEffect` that calls
 * `syncAnnotation` directly and tells no callback about it. So the trigger comes
 * off the SSE stream instead — which also means it holds for the prebuilt
 * upstream bundle we can roll back to, exactly like `belongsToLink`.
 *
 * ⚠️ WHY THE ANSWER GOES IN `note` AND NOT `comment`
 * While a drag is being refined the toolbar PATCHes its own annotation with a
 * regenerated `comment`. An instruction written there survives until the
 * reviewer nudges the element one more time, and then it is coordinates again.
 *
 * ⚠️ WHY THERE IS A "REMOVE" AND WHY IT IS NOT A DELETE
 * Layout mode is the one surface where a reviewer can say something by accident:
 * a stray click in placement mode drops a component on the page and syncs it as
 * real feedback. This panel is the moment they find out, so it is the right
 * place to offer taking it back — but it posts to `/withdraw` (status →
 * `dismissed`), never `DELETE`. A deleted row emits no SSE frame, so the toolbar
 * would never learn, the placement would stay in its own state and localStorage,
 * and the next page load would re-create it. The tombstone is what makes it go.
 */

const LAYOUT_KINDS = new Set(["placement", "rearrange"]);

/**
 * ⚠️ Must NOT start with "agentation" — the collab KV bridge mirrors every
 * `agentation*` key into the link's SHARED store, which would make "I have been
 * asked about this drag" a global fact. Two reviewers, and the second one's drag
 * would be silently marked as already handled. Same trap as `sk-replyseen_`.
 */
import { createHost } from "./ui.js";

const ASKED = "sk-layoutasked_";

/**
 * How recent a layout annotation has to be for us to interrupt someone about it.
 *
 * The stream replays seven days on a fresh connection, which is right for
 * questions an agent asked and very wrong here: without a window, every reviewer
 * opening the link would be asked to explain a week of other people's drags.
 * Ten minutes is "you are still in the session that made this".
 */
const RECENT_MS = 10 * 60 * 1000;

/**
 * The four upstream intents, phrased as what a person moving a box means.
 *
 * One word each, because four chips have to sit on ONE row inside a 320px
 * panel — "Change this / It's broken / Just exploring / Looks right" wrapped to
 * two rows, which is 30px of height spent on nothing.
 */
const INTENTS = [
  ["change", "Change"],
  ["fix", "Broken"],
  ["question", "Exploring"],
  ["approve", "Approve"],
];

/**
 * Should this frame open the prompt?
 *
 * Exported and pure so it can be tested without a DOM — which matters more here
 * than the shape of the panel does. Every one of these gates fails *silently*:
 * get one wrong and the prompt either never appears (indistinguishable from
 * nobody using layout mode) or appears for a week of other people's drags. Both
 * look like "the feature isn't running" from the outside.
 *
 * @param {object} payload  an SSE frame's payload
 * @param {(id: string) => boolean} asked  has this browser already offered?
 * @param {number} now
 */
export function shouldAsk(payload, asked, now = Date.now()) {
  if (!payload?.id || !LAYOUT_KINDS.has(payload.kind)) return false;
  // Settled — the agent has closed it and the drag is no longer a live question.
  if (payload.status === "resolved" || payload.status === "dismissed") return false;
  // Answered, by anyone. The column is the record, so a second reviewer opening
  // the page is not asked to re-explain a drag that already has an instruction.
  if (payload.note) return false;
  // The stream replays 7 days on a fresh connection. Without a window, opening
  // any link would mean being asked about every drag anyone ever made on it.
  if (!(now - Number(payload.createdAt || 0) < RECENT_MS)) return false;
  // Offering twice is nagging, and the drag is already saved either way.
  if (asked(payload.id)) return false;
  return true;
}

export function createLayoutIntent({ endpoint }) {
  const queue = new Map(); // annotationId -> { kind, comment }
  let ui = null;
  let chosen = "change";

  const asked = (id) => {
    try { return localStorage.getItem(ASKED + id) === "1"; } catch { return false; }
  };
  const markAsked = (id) => {
    try { localStorage.setItem(ASKED + id, "1"); } catch { /* private mode */ }
  };

  /**
   * Turn the toolbar's generated comment into something worth showing back.
   *
   * Deliberately NOT the raw string: "Move Hero section (section) — from
   * (12,340) 400×200 to (36,240) 400×200" is what we are apologising for. The
   * reviewer knows what they just dragged; the panel only has to identify it
   * well enough that they know which drag is being asked about.
   */
  function summarise(kind, comment) {
    const text = String(comment || "");
    if (kind === "placement") {
      const m = text.match(/^Place\s+(\w[\w-]*)/i);
      return m ? `You placed a ${m[1]} here.` : "You placed a new component here.";
    }
    const m = text.match(/^Move\s+(.+?)\s+section/i);
    return m ? `You moved ${m[1]}.` : "You moved something on the page.";
  }

  function build() {
    const { host, root, el } = createHost(`
      /* ⚠️ Bottom CENTRE, not bottom right.
         It sat at right:16/bottom:84 — directly on top of Layout Mode's own
         palette, which occupies the full right edge whenever layout mode is
         open. So the question about the drag covered the panel you make drags
         with, and answering it meant losing your place. Centre clears the
         palette on the right and our own "Edit text" pill on the left. */
      .panel { left: 50%; transform: translateX(-50%); bottom: 84px;
        width: 320px; max-width: calc(100vw - 24px); }
      /* Green: this is a confirmation flow, not an alert. The move already
         saved; nothing here can go wrong. */
      .panel { --sk-accent: #30A46C; }
      .hd { padding: 7px 9px 7px 11px; }
      /* Not the shared .grow class — that one restyles font and colour for the
         header's status text, which is wrong for an icon button. */
      .hd .iconbtn { margin-left: auto; }
      .body { padding: 8px 11px 9px; }
      /* One muted line, not a boxed callout. The reviewer knows what they just
         dragged — this only has to say WHICH drag is being asked about, and a
         framed box around six words was pure height. */
      .what { font-size: 11.5px; color: var(--sk-text-2); margin-bottom: 7px;
        white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
      /* nowrap: four one-word chips fit one row at 320px, and letting them wrap
         is how this panel grew a row it did not need. */
      .chips { display: flex; flex-wrap: nowrap; gap: 4px; margin-bottom: 7px; }
      .chip { font-size: 11px; padding: 3px 8px; white-space: nowrap; }
      /* Single line to start, grows as they type. A 56px box that is empty most
         of the time reads as a form to fill in rather than a quick aside. */
      textarea { min-height: 32px; font-size: 12px; padding: 6px 8px; }
      .row { display: flex; gap: 6px; align-items: center; margin-top: 7px; }
      .row .grow { margin-left: auto; }
      button.primary { padding: 5px 11px; font-size: 12px; }
      /* Withdrawing is destructive, so it does not get accent weight or a spot
         under the thumb — it is a quiet ghost at the far end, red only on hover. */
      button.danger { color: var(--sk-text-3); }
      button.danger:hover { background: color-mix(in srgb, #E5484D 16%, transparent); color: #E5484D; }
      button.ghost[disabled] { opacity: .4; cursor: default; background: none; }
    `);
    root.append(Object.assign(document.createElement("div"), { innerHTML: `
      <div class="panel" role="dialog" aria-label="Explain this layout change">
        <div class="hd"><span class="dot"></span><span id="title">Why this change?</span>
          <button class="iconbtn" id="skipx" aria-label="Skip" title="Skip — the change is saved either way">✕</button></div>
        <div class="body">
          <div class="what" id="what"></div>
          <div class="chips" id="chips"></div>
          <textarea id="why" rows="1" placeholder="Optional — e.g. pricing above the fold"></textarea>
          <div class="row">
            <button class="primary" id="send">Save</button>
            <span class="status" id="nav"></span>
            <button class="ghost danger grow" id="remove"
              title="Remove this change from the page and from the feedback list">Remove</button>
          </div>
        </div>
      </div>` }).firstElementChild);

    for (const [value, label] of INTENTS) {
      const b = document.createElement("button");
      b.className = "chip";
      b.type = "button";
      b.dataset.intent = value;
      b.setAttribute("aria-pressed", String(value === chosen));
      b.textContent = label;
      b.addEventListener("click", () => {
        chosen = value;
        for (const c of el("chips").children) {
          c.setAttribute("aria-pressed", String(c.dataset.intent === chosen));
        }
      });
      el("chips").append(b);
    }
    el("skipx").addEventListener("click", () => skipCurrent());
    el("send").addEventListener("click", () => send());
    el("remove").addEventListener("click", () => withdraw());
    el("why").addEventListener("keydown", (e) => {
      if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); }
      // The toolbar binds single-key shortcuts on document — "L" typed in here
      // would otherwise drop the reviewer back out of layout mode mid-sentence.
      e.stopPropagation();
    });
    return { host, root, el };
  }

  function render() {
    const list = [...queue.entries()];
    if (!list.length) {
      // `current` is cleared with the panel, not left pointing at the drag that
      // was just answered — every action reads it, and a hidden panel whose
      // buttons still address a settled annotation is a click away from a
      // confusing 404.
      if (ui) { ui.host.style.display = "none"; ui.current = null; }
      return;
    }
    if (!ui) ui = build();
    ui.host.style.display = "";
    const [id, item] = list[0];
    ui.el("what").textContent = summarise(item.kind, item.comment);
    ui.el("why").value = "";
    // ⚠️ Reset the intent with the text box, not just the text box.
    //
    // The panel is a QUEUE — answering one advances to the next drag — and the
    // chip kept its previous selection across that step. So a reviewer who
    // marked one move "It's broken" and then explained two more in prose would
    // have silently filed all three as broken, with the answer they gave sitting
    // right there looking correct. Found by driving the real queue, because with
    // only one question in it the bug cannot happen.
    chosen = "change";
    for (const c of ui.el("chips").children) {
      c.setAttribute("aria-pressed", String(c.dataset.intent === chosen));
    }
    ui.el("send").disabled = false;
    ui.el("remove").disabled = false;
    ui.el("nav").textContent = list.length > 1 ? `+${list.length - 1} more` : "";
    ui.current = id;
    // Focused on open: this panel exists to be typed into, and a reviewer who
    // has to click into the box first is a reviewer who skips it.
    try { ui.el("why").focus({ preventScroll: true }); } catch { /* older browsers */ }
  }

  /**
   * Skip is a real answer, and it is recorded as one.
   *
   * Unlike the reply panel's ✕ — which parks a question so it comes back —
   * being asked "why did you drag that" twice is nagging, and the drag itself is
   * already safely stored. So this marks it asked and moves on.
   */
  function skipCurrent() {
    const id = ui?.current;
    if (!id) return;
    markAsked(id);
    queue.delete(id);
    render();
  }

  /**
   * Take the drag back.
   *
   * The one thing this panel could not do, and the reason it was asked for: a
   * stray click in placement mode drops a component on the page, syncs it as
   * real feedback, and then asks you to justify it. The honest answer is often
   * "I didn't mean to do that", and there was nowhere to say it — the toolbar's
   * own ✕ sits on the placement box, which is only reachable while layout mode
   * is open, and a rearrange has no ✕ at all.
   *
   * ⚠️ `/withdraw`, not `DELETE`. See the file header: a deleted row emits no
   * SSE frame, so the toolbar keeps the placement in state and in localStorage
   * and re-creates it on the next load. The `dismissed` tombstone is the frame
   * it listens for, and reacting to it is what actually clears the page.
   *
   * The panel closes on the optimistic path rather than waiting: the reviewer
   * has said this was a mistake, so leaving the question on screen for a round
   * trip is the wrong direction to fail in. A failure puts it back with a reason.
   */
  async function withdraw() {
    const id = ui?.current;
    if (!id) return;
    ui.el("remove").disabled = true;
    ui.el("nav").textContent = "Removing…";
    try {
      const res = await fetch(`${endpoint}/annotations/${id}/withdraw`, { method: "POST" });
      if (!res.ok) throw new Error(String(res.status));
      markAsked(id);
      queue.delete(id);
      ui.el("nav").textContent = "✓ Removed";
      setTimeout(render, 700);
    } catch {
      ui.el("remove").disabled = false;
      ui.el("nav").textContent = "Could not remove — try again";
    }
  }

  async function send() {
    const id = ui?.current;
    const note = ui.el("why").value.trim();
    if (!id) return;
    if (!note) return skipCurrent(); // an empty box is a skip, not an error
    ui.el("send").disabled = true;
    ui.el("nav").textContent = "Saving…";
    try {
      const res = await fetch(`${endpoint}/annotations/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        // `note`, never `comment` — see the header. `intent` is the reviewer's
        // pick replacing the hardcoded "change" every layout annotation carries.
        body: JSON.stringify({ note, intent: chosen }),
      });
      if (!res.ok) throw new Error(String(res.status));
      markAsked(id);
      queue.delete(id);
      ui.el("nav").textContent = "✓ Saved";
      setTimeout(render, 900);
    } catch {
      ui.el("send").disabled = false;
      ui.el("nav").textContent = "Could not save — try again";
    }
  }

  /**
   * Called for every SSE frame. The decision lives in `shouldAsk`; this applies
   * it, and additionally retracts a question that has stopped being one — a
   * drag answered or resolved from another tab must not stay on screen here.
   */
  function ingest(payload) {
    if (!payload?.id || !LAYOUT_KINDS.has(payload.kind)) return;
    const settled = payload.status === "resolved" || payload.status === "dismissed" || payload.note;
    if (settled) { if (queue.delete(payload.id)) render(); return; }
    if (queue.has(payload.id)) return;
    if (!shouldAsk(payload, asked)) return;
    queue.set(payload.id, { kind: payload.kind, comment: payload.comment || "" });
    render();
  }

  return { ingest, pending: () => queue.size };
}
